// romdb.cpp - the known-ROM database.
//
// Four groups, in priority order (when several names exist for one ROM, the first group that has it wins;
// `IdentifyAll` returns every match):
//   1. kDocumented : NEC PC-6000 family names from the PC6001V / PC6001VX documentation (hand-checked)
//   2. kShortNames : the short names everybody uses (fMSX / libretro MSX set, NP2kai PC-98 files)
//   3. blueMSX     : generated by tools/gen_romdb.py from msxsysromdb.xml (ROM title + SHA-1; romdb_bluemsx.inc).
//                    MSX ROMs are shared by dozens of machines, so a neutral title beats an arbitrary machine's file name
//   4. MAME        : generated by tools/gen_romdb.py from the MAME driver sources (file name, size, CRC-32, SHA-1; romdb_mame.inc)
//
// To add a ROM by hand: append a line {name, size, crc32, md5, sha1, system} to kShortNames. Use 0 / nullptr
// for hashes you do not have (at least one is required). Hashes are lower-case hex. An entry matches only when
// its size and every listed hash agree.
#include "romdb.h"

#include <algorithm>
#include <cstring>
#include <unordered_map>

#include "crypto.h"

